"""The scripted baseline: toward food if safe, else any safe move, else straight (BASE-02)."""

from pathlib import Path

import numpy as np

from rllab.core import Agent, Transition
from rllab.envs import COMPACT_FIELDS

STRAIGHT, LEFT, RIGHT = 0, 1, 2
# Relative moves in tie order, each with its danger field and its quarter turns clockwise.
_MOVES = (
    (STRAIGHT, COMPACT_FIELDS.index("danger_straight"), 0),
    (LEFT, COMPACT_FIELDS.index("danger_left"), -1),
    (RIGHT, COMPACT_FIELDS.index("danger_right"), 1),
)
# Absolute directions clockwise from up: the heading and the food field for each.
_HEADING = [COMPACT_FIELDS.index(f"head_{d}") for d in ("up", "right", "down", "left")]
_FOOD = [COMPACT_FIELDS.index(f"food_{d}") for d in ("up", "right", "down", "left")]


def _choose(row: np.ndarray) -> int:
    """One agent's move: the first safe move toward food, else the first safe move, else straight."""
    heading = int(np.argmax(row[_HEADING]))
    safe = [(move, turn) for move, danger, turn in _MOVES if row[danger] == 0.0]
    for move, turn in safe:
        if row[_FOOD[(heading + turn) % 4]] == 1.0:
            return move
    return safe[0][0] if safe else STRAIGHT


class ScriptedPlayer(Agent):
    """Deterministic rules on the compact view; ties go straight, then left, then right."""

    def act(self, obs: np.ndarray, *, explore: bool) -> np.ndarray:
        """One move per agent for `(n_agents, 11)` compact observations; `explore` changes nothing."""
        if obs.ndim != 2 or obs.shape[1:] != (len(COMPACT_FIELDS),):
            raise ValueError(f"expected observations of shape (n_agents, 11), got {obs.shape}")
        return np.array([_choose(row) for row in obs], dtype=np.int64)

    def learn(self, t: Transition) -> None:
        """Discard `t`: the scripted player never learns."""
        del t

    def save(self, path: Path) -> None:
        """Write an empty checkpoint: the rules hold no state."""
        path.write_bytes(b"")

    def load(self, path: Path) -> None:
        """Check the checkpoint exists: the rules hold no state to read."""
        if not path.exists():
            raise FileNotFoundError(path)

